open Raster2
let ok=function Ok x->x|Error _->failwith"multisample error"
let render frame samples=let value=ok(Multisample.create~width:3~height:2~samples~pitch:(3*samples*8+5)())in Bytes.fill(Multisample.bytes value)0(Bytes.length(Multisample.bytes value))'\x7f';ok(Multisample.clear value~color:0x000000ffl~depth:1.);for sample=0 to samples-1 do let color=Int32.of_int((((frame+sample)land 255)lsl 24)lor 0xff)in assert(ok(Multisample.test_and_write value~compare:Less~depth_write:true~x:0~y:0~sample~depth:(0.5+.float sample/.float(2*samples))~color))done;assert(not(ok(Multisample.test_and_write value~compare:Less~depth_write:true~x:0~y:0~sample:0~depth:0.9~color:0xffffffffl)));let target=ok(Surface.create~width:3~height:2())in ok(Multisample.resolve value target);assert(Bytes.get(Multisample.bytes value)(3*samples*8)='\x7f');Bytes.copy(Surface.bytes target)
let ()=List.iter(fun samples->for index=0 to samples-1 do ignore(ok(Multisample.sample_position~samples index))done;List.iter(fun frame->let expected=render frame samples in let workers=Array.init 4(fun _->Domain.spawn(fun()->render frame samples))in Array.iter(fun worker->assert(Domain.join worker=expected))workers)[1;600])[1;2;4;8;9;16];let two=render 0 2 in assert(Bytes.get two 0=Char.chr 1);(match Multisample.create~width:1~height:1~samples:3()with Error(Multisample.Invalid_sample_count 3)->()|_->failwith"sample count");(match Multisample.create~width:2~height:1~samples:4~pitch:63()with Error Multisample.Invalid_pitch->()|_->failwith"short pitch");print_endline"Raster2 deterministic multisample resolve passed"
